<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Content;use Acorn\SafetyHealthcheck\Database\Schema;
final class SeedContent{
 public static function installIfEmpty():void{global $wpdb;$vt=Schema::table('content_versions');if((int)$wpdb->get_var("SELECT COUNT(*) FROM $vt"))return;$now=current_time('mysql');$wpdb->insert($vt,['version_key'=>'1.0','status'=>'published','created_at'=>$now,'published_at'=>$now,'notes'=>'V1 content pending Acorn technical sign-off']);$v=(int)$wpdb->insert_id;foreach(require dirname(__DIR__,2).'/config/questions.php' as $q){$wpdb->insert(Schema::table('questions'),['content_version_id'=>$v,'question_key'=>$q['question_key'],'module_key'=>$q['module_key'],'sort_order'=>$q['sort_order'],'question_text'=>$q['question_text'],'help_text'=>$q['help_text'],'variant_json'=>wp_json_encode(self::variants($q['question_key'])),'applicability_json'=>wp_json_encode(self::applicabilityForQuestion($q['question_key'])),'answer_rules_json'=>wp_json_encode(['yes'=>'addressed','partly'=>'review','no'=>$q['no_status'],'not_sure'=>$q['not_sure_status'],'subject'=>$q['subject']]),'source_json'=>wp_json_encode(SourceMetadata::versionedQuestionSources($q['question_key'])),'last_reviewed'=>'1970-01-01','next_review'=>'2026-09-17','reviewed_by'=>'','is_active'=>1]);foreach(['partly','no','not_sure'] as $a){$status=$a==='partly'?'review':$q[$a.'_status'];$identified=$a==='partly'?"Your answer indicates that {$q['subject']} is only partly in place or may not fully reflect the organisation's current circumstances.":($a==='no'?"Your answer indicates that {$q['subject']} may not currently be in place.":"You were not sure whether {$q['subject']} is currently in place.");$next=($a==='not_sure'?'Confirm the current position and who is responsible. Then consider this next step: ':'').$q['next_step'];$tags=self::tags($q['question_key']);$jurisdictions=str_starts_with($q['question_key'],'F')?['england','wales','scotland','northern_ireland']:(str_starts_with($q['question_key'],'L')||str_starts_with($q['question_key'],'AS')?['*','northern_ireland']:['*']);foreach($jurisdictions as $jurisdiction)$wpdb->insert(Schema::table('recommendations'),['content_version_id'=>$v,'question_key'=>$q['question_key'],'answer_value'=>$a,'jurisdiction'=>$jurisdiction,'finding_status'=>$status,'heading'=>ucfirst($q['subject']),'identified_text'=>$identified,'next_step_text'=>$next,'why_text'=>$q['why'],'good_looks_text'=>$q['good_looks'],'service_tags_json'=>wp_json_encode($tags),'source_json'=>wp_json_encode(SourceMetadata::forQuestion($q['question_key'],$jurisdiction)),'sort_rank'=>$q['sort_order']]);}}}
 public static function applicabilityForQuestion(string $k):array{$employees=['has_employees'=>true];$nonHome=['non_home_workplace'=>true];$premises=['field'=>'premises_responsibility','not_in'=>['no']];if(in_array($k,['M04_CONSULTATION','R03_HIGHER_NEEDS','T01_INDUCTION','T02_TRAINING_SUPERVISION','T03_TRAINING_RECORDS','A01_FIRST_AID','A02_INCIDENTS','A03_RIDDOR'],true))return$employees;if($k==='W01_WELFARE')return['any'=>[$nonHome,$premises]];if($k==='W02_WORK_EQUIPMENT')return['any'=>[$nonHome,['risk_flag'=>'machinery']]];if(str_starts_with($k,'F'))return['all'=>[$premises,$nonHome]];if(str_starts_with($k,'L'))return['field'=>'water_system_responsibility','in'=>['yes','partly','not_sure']];if(str_starts_with($k,'AS')){$rules=[['field'=>'maintenance_repair_responsibility','in'=>['yes','partly','not_sure']],['field'=>'building_pre_2000','in'=>['yes','not_sure']]];if($k==='AS04_ASBESTOS_INTRUSIVE')$rules[]=['field'=>'intrusive_work_planned','in'=>['yes','not_sure']];return['all'=>$rules];}$flags=['C01_COSHH'=>'hazardous_substances','D01_DSE'=>'dse','MH01_MANUAL_HANDLING'=>'manual_handling','LW01_LONE_WORKING'=>'lone_working','WAH01_WORK_AT_HEIGHT'=>'work_at_height','YW01_YOUNG_WORKERS'=>'young_workers','CT01_CONTRACTORS'=>'contractors','DRV01_DRIVING'=>'driving_for_work'];return isset($flags[$k])?['risk_flag'=>$flags[$k]]:['all'=>[]];}
 private static function variants(string $k):array{return $k==='M02_POLICY'?['under_5'=>'Are clear health and safety arrangements in place and kept current?','5_plus'=>'Are clear health and safety arrangements in place, including a current written policy?']:[];}
 private static function tags(string $k):array{if(str_starts_with($k,'F'))return['fire'];if(str_starts_with($k,'L'))return['legionella'];if(str_starts_with($k,'AS'))return['asbestos'];$t=['health_safety'];if(str_starts_with($k,'T'))$t[]='training';return$t;}
}
